<?php require __DIR__.'/../app/config/config.php';$roles=[];foreach(db()->query('SELECT id,name FROM roles') as $r)$roles[$r['name']]=$r['id'];$users=[['member','membre@urbanfit.fr','Membre','Démo','URBAN2026'],['coach','coach@urbanfit.fr','Sarah','Coach','URBAN2026'],['admin','admin@urbanfit.fr','Admin','PENDAFITNESS','STUDI2026']];foreach($users as [$role,$email,$first,$last,$pwd]){$s=db()->prepare('INSERT INTO users(role_id,firstname,lastname,email,password,phone,city) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE password=VALUES(password),role_id=VALUES(role_id),active=1');$s->execute([$roles[$role],$first,$last,$email,password_hash($pwd,PASSWORD_DEFAULT),'0600000000','Paris']);echo "$role: $email / $pwd\n";}